 export const TASA_IVA = 0.13;

+// Tasa de IVA configurable por entorno: TASA_IVA es un número entre 0 y 1; sin definir vale TASA_IVA.
+export function tasaIva(env = process.env) {
+  const valor = env.TASA_IVA;
+  if (valor === undefined) return TASA_IVA;
+  const tasa = Number(valor);
+  if (typeof valor !== "string" || valor.trim() === "" || !Number.isFinite(tasa) || tasa < 0 || tasa > 1)
+    throw new RangeError(`TASA_IVA inválida: ${JSON.stringify(valor)} (debe ser un número entre 0 y 1)`);
+  return tasa;
+}
